685	  if (BLOSCLZ_UNLIKELY(length == 0)) {
686	    return 0;
687	  }
688	  ctrl = (*ip++) & 31U;
689	
690	  while (1) {
691	    if (ctrl >= 32) {
692	      // match
693	      int32_t len = (int32_t)(ctrl >> 5U) - 1 ;
694	      int32_t ofs = (int32_t)(ctrl & 31U) << 8U;
695	      uint8_t code;
696	      const uint8_t* ref = op - ofs;
697	
698	      if (len == 7 - 1) {
699	        do {
700	          if (BLOSCLZ_UNLIKELY(ip + 1 >= ip_limit)) {
701	            return 0;
702	          }
